 const zoomBar=document.createElement('div');zoomBar.id='scene-zoom3d';zoomBar.className='scene-zoom3d';zoomBar.title='Колесо — масштаб · Shift + перетаскивание — сдвиг';zoomBar.hidden=true;zoomBar.innerHTML='<button id="zoom3d-out" aria-label="Отдалить 3D" title="Отдалить">−</button><output id="zoom3d-value" aria-label="Масштаб 3D">100%</output><button id="zoom3d-in" aria-label="Приблизить 3D" title="Приблизить">+</button>';document.querySelector('.canvas-panel').append(zoomBar);$('zoom3d-out').onclick=()=>setZoom3d(state.zoom3d/1.25);$('zoom3d-in').onclick=()=>setZoom3d(state.zoom3d*1.25);
