 $('focus-object').onclick=()=>{try{planFrame=planObjectFrame(p,{kind:state.object==='well'?'well':'edge',id:state.object==='well'?state.wellId:state.edgeId});state.zoom=1;renderCanvas()}catch(error){notify(error.message)}};$('show-report').onclick=()=>{flushEdit();state.page=state.page==='report'?'scene':'report';render()};$('results-scope').onchange=ev=>{state.resultsScope=ev.target.value;renderResults()};
 $('project-info').onclick=()=>{$('project-details').hidden=!$('project-details').hidden;$('project-menu').open=false};
 document.addEventListener('focusin',ev=>beginEdit(ev.target));document.addEventListener('focusout',ev=>{if(editSession?.node===ev.target){flushEdit();setTimeout(syncInputs,0)}});
