function renderInspector(){const title=$('inspector-title').textContent,open=new Map([...$('inspector').querySelectorAll('details.inspector-block')].map(v=>[v.querySelector('summary').textContent,v.open]));renderInspectorContent();if(title===$('inspector-title').textContent)for(const v of $('inspector').querySelectorAll('details.inspector-block')){const key=v.querySelector('summary').textContent;if(open.has(key))v.open=open.get(key)}renderValidation()}
