 const tabs=isWell?[['geometry','Колодец'],['excavation','Котлован'],['bedding','Засыпка'],['soils','Грунты']]:[['geometry','Труба'],['trench','Траншея'],['bedding','Засыпка'],['soils','Грунты']];if(!tabs.some(v=>v[0]===state.inspectorTab))state.inspectorTab='geometry';
