function renderBeddingMetrics(){const pipeSketch=$('pipe-parameters-sketch'),route=edge(),resolved=route&&result.edges[route.id]?.res;if(pipeSketch&&resolved)pipeSketch.innerHTML=pipeParametersSketch(route,resolved);const trenchSketch=$('trench-parameters-sketch'),zone=route?.sections[state.section];if(trenchSketch&&resolved&&zone)trenchSketch.innerHTML=trenchParametersSketch(route,zone,crossSection(route,resolved,zone,state.ratio*resolved.length));const sketch=$('well-parts-sketch');if(sketch&&well())sketch.innerHTML=wellPartsSketch(well(),wellGeometry(well(),p));const pitSketch=$('well-pit-sketch');if(pitSketch&&well())pitSketch.innerHTML=wellPitSketch(well(),wellGeometry(well(),p));const pitNote=$('inspector').querySelector('[data-pit-dimensions]');if(pitNote&&well())pitNote.textContent=pitSizeNote(wellGeometry(well(),p));const total=$('fill-totals'),isWell=state.object==='well'&&state.scale==='object',r=isWell?result.wells[well()?.id]:result.edges[edge()?.id];if(total)total.innerHTML=fillTotals(r,!!r&&!r.errors.length);const neck=$('inspector').querySelector('[data-derived="neck-auto"]');if(neck&&well())neck.textContent=fmt(wellGeometry(well(),p).neckHeight)+' м';const node=$('bedding-metrics');if(node)node.innerHTML=beddingMetricsHTML();const e=edge(),res=e&&result.edges[e.id]?.res,s=e?.sections[state.section];if(e&&res&&s&&$('bedding-detail'))$('bedding-detail').innerHTML=beddingDetail(e,res,s)}
function beddingDetail(e,res,s){
 const c=crossSection(e,res,s,state.ratio*res.length),radius=c.radius,th=s.bedding,scale=Math.min(220/Math.max(c.width,2*radius+.4),155/Math.max(.3,2*radius+th)),cx=160,base=210,axis=base-(th+radius)*scale,yTop=base-th*scale,bedTop=(c.width+(c.left+c.right)*th)*scale;
 return `<svg viewBox="0 0 320 280" aria-label="Узел основания трубы" role="img"><defs><pattern id="bedding-hatch" width="9" height="9" patternUnits="userSpaceOnUse"><rect width="9" height="9" fill="${beddingColor(s)}"/><path d="M0 9L9 0" stroke="#ae8137" stroke-width="1"/></pattern></defs><path d="M30 ${base}H290" stroke="#89939e" stroke-width="2"/><polygon points="${cx-c.width*scale/2},${base} ${cx+c.width*scale/2},${base} ${cx+bedTop/2},${yTop} ${cx-bedTop/2},${yTop}" fill="url(#bedding-hatch)" stroke="#a97725"/><circle cx="160" cy="${axis}" r="${radius*scale}" fill="${s.casing?'#d9e2e9':'#f97316'}" stroke="#465c6a" stroke-width="2"/>${s.casing?`<circle cx="160" cy="${axis}" r="${e.diameter/2*scale}" fill="#f97316" stroke="#b94d13"/>`:''}<path d="M40 ${yTop}H20V${base}H40" fill="none" stroke="#aa641b" stroke-width="2"/><text x="22" y="${yTop-10}" class="bed-thickness-label">h = ${fmt(th,2)} м</text><text x="160" y="245" text-anchor="middle">${th>0?esc(s.beddingMaterial||'ЩПС'):'Без искусственной подушки'} · b = ${fmt(c.width)} м</text></svg>`;
}
