 const neck=field('Диаметр горловины внутри',base+'.neckDiameter',w.neckDiameter,{unit:'м'})+field('Толщина стенки горловины',base+'.neckWall',w.neckWall,{unit:'м'})+block('Сместить горловину от центра',`<p class="task-note">0 / 0 — горловина по центру колодца.</p><div class="two">${field('Сдвиг вдоль X',base+'.neckX',w.neckX,{unit:'м'})}${field('Сдвиг вдоль Y',base+'.neckY',w.neckY,{unit:'м'})}</div>`,false);
