function calculate(options={}){try{result=calculateNetwork(p,options)}catch(error){result={wells:{},edges:{},total:{},errors:[error.message],issues:[{kind:'network',objectId:p.id,code:'calculation',severity:'error',message:'Проверьте исходные данные: '+error.message,paths:[],tab:'geometry'}],warnings:[],valid:false};notify('Ошибка исходных данных: '+error.message)}}
